// Package tsobjc wraps the tree-sitter Objective-C grammar for astkit.
//
// astkit's other grammars come from the vendored fork
// github.com/smacker/go-tree-sitter, which does not include Objective-C.
// This package vendors the grammar directly from
// https://github.com/tree-sitter-grammars/tree-sitter-objc (MIT licensed;
// see LICENSE in this directory), following the exact same shape as every
// per-language package in the smacker fork (parser.c + parser.h + a
// binding.go cgo wrapper). parser.c is machine-generated by the tree-sitter
// CLI from that project's grammar.js — see NOTICE for provenance and how to
// regenerate/update it.
package tsobjc

//#include "parser.h"
//TSLanguage *tree_sitter_objc();
import "C"
import (
	"unsafe"

	sitter "github.com/smacker/go-tree-sitter"
)

// GetLanguage returns the Objective-C tree-sitter grammar.
func GetLanguage() *sitter.Language {
	ptr := unsafe.Pointer(C.tree_sitter_objc())
	return sitter.NewLanguage(ptr)
}
